  text('button-note', demo ? '画面確認のみ。実際のラベルは出ません。' : '印刷結果は、この画面に表示されます。');
  document.querySelectorAll('.retry-button').forEach(b => { b.disabled = busy || checking || !!unresolved || (!demo && (!android || !storageOK)); });
